const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z"/>',funnel:'<path d="M3 4h18l-7 8v7l-4 2v-9Z"/>',swap:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',home:'<path d="m3 10 9-7 9 7v11H3Zm6 11v-8h6v8"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a17 17 0 0 1 0 18 17 17 0 0 1 0-18"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v5m10-5v5M3 11h18"/>',chart:'<path d="M3 21V3m0 18h18M7 16l5-6 4 3 5-8"/>',megaphone:'<path d="m3 9 17-6v18L3 15Zm3 7v5h4l-1-4"/>',users:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3m0-18a4 4 0 0 1 0 8m3 3a6 6 0 0 1 3 7"/>',settings:'<path d="m10 2 4 0 1 3 3 2 3-1 2 4-2 2v3l2 2-2 4-3-1-3 2-1 2h-4l-1-3-3-2-3 1-2-4 2-2v-3l-2-2 2-4 3 1 3-2Z"/><circle cx="12" cy="12" r="3"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',plus:'<path d="M12 4v16M4 12h16"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',check:'<path d="m4 12 5 5L20 6"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3v1"/>',menu:'<path d="M3 5h18M3 12h18M3 19h18"/>',play:'<path d="m8 4 13 8-13 8Z"/>',mic:'<rect x="8" y="2" width="8" height="13" rx="4"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',file:'<path d="M4 2h10l6 6v14H4Zm10 0v7h6M7 13h10M7 17h7"/>',phone:'<path d="m4 3 4-1 3 6-3 2a14 14 0 0 0 6 6l2-3 6 3-1 4c-1 5-21-4-17-17Z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const btn=(label,act='save',cls='',extra='')=>`<button type="${act==='submit'?'submit':'button'}" class="btn ${cls}" data-action="${act}" ${extra}>${label}</button>`;
const chip=(t,c='')=>`<span class="chip ${c}">${t}</span>`;
const money=v=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const state={role:localStorage.getItem('cetro-role')||'manager',person:'Blanca',route:'painel',tab:'',leadTab:'Lead',propertyTab:'Geral',propertyType:'Empreendimento',selectedProperty:0,available:true,guide:false,selectedLead:0,chat:0,...JSON.parse(localStorage.getItem('cetro-demo')||'{}')};
const people=['Blanca','Ezequiel','Fernando','Gigi','Jeferson','Nádia','Natalia','Sil','Veronica'];
const leads=[{name:'Marina Andrade',initials:'MA',product:'Antunes Beach Resort',owner:'Blanca',stage:'Lead',temp:'Morno',budget:650000,origin:'Meta Ads',note:'Busca um imóvel de frente para o mar para uso da família e renda.'},{name:'Lucas Ribeiro',initials:'LR',product:'Croas de São Bento',owner:'Sil',stage:'Atendimento qualificado',temp:'Quente',budget:180000,origin:'Site',note:'Quer um lote próximo à praia. Entrada disponível e prazo de compra de 60 dias.'},{name:'Beatriz Costa',initials:'BC',product:'Villa Camboa',owner:'Ezequiel',stage:'Agendamento',temp:'Quente',budget:540000,origin:'WhatsApp',note:'Videochamada marcada para amanhã às 15h.'},{name:'Rafael Martins',initials:'RM',product:'Horizon Smart Flats',owner:'Blanca',stage:'Visita',temp:'Quente',budget:490000,origin:'Portal',note:'Visitou o empreendimento. Aguardando simulação da unidade escolhida.'},{name:'Isabela Santos',initials:'IS',product:'Gran Mirat',owner:'Veronica',stage:'Proposta',temp:'Quente',budget:520000,origin:'Meta Ads',note:'Proposta enviada; analisando forma de pagamento.'},{name:'Pedro Almeida',initials:'PA',product:'Antunes Beach Resort',owner:'Sil',stage:'Venda',temp:'Quente',budget:625000,origin:'Indicação',note:'Venda registrada. Iniciar acompanhamento de pós-venda.'},{name:'Sofia Mendes',initials:'SM',product:'Mirante de Maragogi',owner:'Blanca',stage:'NOVO',temp:'Frio',budget:210000,origin:'Meta Ads',note:'Aguardando captura no funil principal.'},{name:'Thiago Lopes',initials:'TL',product:'Croas de São Bento',owner:'Nádia',stage:'Atendimento Frio',temp:'Frio',budget:160000,origin:'WhatsApp',note:'Sem resposta ao primeiro contato.'}];
const properties=[{name:'Antunes Beach Resort',type:'Empreendimento',location:'Praia de Antunes · Maragogi, AL',price:625000,area:34,rooms:1,img:'assets/imovel-0.jpg'},{name:'Villa Camboa Resort Clube',type:'Empreendimento',location:'Praia de Bitingui · Japaratinga, AL',price:540000,area:42,rooms:1,img:'assets/imovel-1.jpg'},{name:'Mirante de Maragogi',type:'Loteamento',location:'Ponta de Mangue · Maragogi, AL',price:180000,area:200,rooms:0,img:'assets/imovel-2.jpg'},{name:'Croas de São Bento',type:'Terreno',location:'São Bento · Maragogi, AL',price:160000,area:150,rooms:0,img:'assets/imovel-3.jpg'},{name:'Maré Alta Residence',type:'Imóvel pronto',location:'Porto de Galinhas · Ipojuca, PE',price:450000,area:38,rooms:1,img:'assets/imovel-4.jpg'},{name:'Casa Jardim das Palmeiras',type:'Casa',location:'Centro · Maragogi, AL',price:920000,area:180,rooms:3,img:'assets/imovel-5.jpg'}];
const stages=['Lead','Atendimento qualificado','Agendamento','Visita','Proposta','Venda'];
const metrics=['Score','Conversão','Recebidos','1ª resposta','Fluidez no Atendimento','Ligações','Leads trabalhados','Mensagens','Pessoas faladas','Qualificados','Agendamentos','Visitas','Propostas','Vendas','Na mão','Tarefas criadas','Tarefas feitas','Leads atrasados','Perdidos'];
const moduleNames={painel:'Painel',funil:'Funil',atender:'Atender',catraca:'Catraca',imoveis:'Imóveis',cetrolab:'Cetrolab',plantao:'Plantão',operacao:'Visão geral',relatorios:'Relatórios',disparos:'Disparos em massa',fluxos:'Fluxos',redes:'Redes sociais',formularios:'Formulários',base:'Base de leads',equipe:'Equipe',config:'Configurações',conta:'Minha conta',disponibilidade:'Disponibilidade',producao:'Produção',apresentacao:'Apresentação'};
function saveDemo(){localStorage.setItem('cetro-demo',JSON.stringify({available:state.available,person:state.person,scoreCols:state.scoreCols,scoreParticipants:state.scoreParticipants,individualMetrics:state.individualMetrics,notes:state.notes||{},extras:state.extras||{},settings:state.settings||{}}))}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toaster);window.toaster=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function nav(){const item=(key,ic,label=moduleNames[key])=>`<button class="nav-item ${state.route===key?'active':''}" data-route="${key}">${icon(ic)}<span>${label}</span>${key==='atender'?'<span class="badge">4</span>':''}</button>`;return `<aside class="sidebar"><a href="#painel" class="brand"><svg class="brandmark" viewBox="0 0 32 38" fill="none"><path d="M5 8 10 14 16 4 22 14 27 8 24 24H8Z" stroke="currentColor" stroke-width="1.8"/><path d="M9 29h14M12 34h8" stroke="currentColor" stroke-width="1.8"/></svg><div><div class="logo">CETRO</div><small>SOB SEU COMANDO</small></div></a><div class="nav-section">PRINCIPAL</div>${item('painel','grid')}${item('atender','chat')}${item('funil','funnel')}${state.role==='manager'?item('catraca','swap'):''}<div class="nav-section">FERRAMENTAS</div>${item('imoveis','home')}${state.role==='manager'?item('cetrolab','globe'):''}${item('plantao','calendar')}${state.role==='manager'?`<div class="nav-section">GESTÃO</div>${item('operacao','chart','Operação')}<div class="subnav">${item('operacao','chart')}${item('relatorios','file')}</div>${item('disparos','megaphone','Marketing')}<div class="subnav">${item('disparos','megaphone')}${item('fluxos','bolt')}${item('redes','globe')}${item('formularios','file')}</div>${item('base','users')}${item('equipe','users')}`:`<div class="nav-section">MINHA OPERAÇÃO</div>${item('disponibilidade','swap')}${item('producao','chart')}`}<div class="nav-section">CONFIGURAÇÕES</div>${state.role==='manager'?item('config','settings'):''}${item('conta','user')}<div class="nav-foot"><button class="nav-item" data-route="apresentacao">${icon('help')}Guia do projeto</button><div class="profile"><span class="avatar dark">${state.role==='manager'?'FH':'BE'}</span><div style="font-size:10px;color:#e1e8db">${state.role==='manager'?'Fernando Hosken':'Blanca Elizabeth Rech'}<p style="font-size:8px;color:#91ab98">${state.role==='manager'?'Diretoria · acesso gerencial':'Corretora · acesso básico'}</p></div></div></div></aside>`}
function shell(){const role=state.role==='manager';$('#app').innerHTML=`${nav()}<div class="workspace"><header class="topbar"><button class="iconbtn mobilemenu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><div class="breadcrumb">Workspace <span style="padding:0 12px;color:#b8c4b0">/</span><strong>${moduleNames[state.route]}</strong></div><span class="demo">PROTÓTIPO INTERATIVO</span><div class="segmented"><button data-role="manager" class="${role?'active':''}">Gestão</button><button data-role="broker" class="${!role?'active':''}">Corretor</button></div><button class="iconbtn" data-action="guide" aria-label="Orientações desta tela">${icon('help')}</button><span class="avatar">${role?'FH':'BE'}</span></header><main class="content" id="main">${renderPage()}</main></div><button class="guidebtn" data-action="guide">${icon('help').replace('<svg','<svg width="16" height="16"')} O que muda nesta tela</button>`;restoreForms()}
function go(route,tab=''){let brokerAllowed=['painel','funil','atender','imoveis','plantao','disponibilidade','producao','conta','apresentacao'];if(state.role==='broker'&&!brokerAllowed.includes(route)){toast('Esta área faz parte do acesso gerencial.');return}state.route=route;state.tab=tab;history.replaceState(null,'','#'+route+(tab?'/'+encodeURIComponent(tab):''));shell();window.scrollTo(0,0)}
function head(title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow" style="margin-bottom:7px">${state.role==='manager'?'OPERAÇÃO · VJ IMÓVEIS':'MEU WORKSPACE'}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function filters(extra=''){return `<div class="filters"><select aria-label="Período" data-filter="period"><option>Este mês · novembro/2026</option><option>Hoje · 10/11/2026</option><option>Ontem · 09/11/2026</option><option>Últimos 7 dias</option><option>Últimos 30 dias</option><option>Personalizado</option></select>${state.role==='manager'?'<select aria-label="Diretoria" data-filter="hier"><option>Todas as diretorias</option><option>Diretoria Comercial</option></select><select aria-label="Gerência" data-filter="hier"><option>Todas as gerências</option><option>Litoral</option><option>Capital</option></select>':''}${extra}<button class="btn tiny" data-action="filters">${icon('settings')} Mais filtros</button><button class="iconbtn" data-action="clearfilters" title="Limpar filtros">${icon('close')}</button></div>`}
function tabs(items,current,kind='tab'){return `<div class="tabs">${items.map(t=>`<button data-${kind}="${t}" class="${current===t?'active':''}">${t}</button>`).join('')}</div>`}
function kpi(label,value,foot='',feature=false){return `<div class="kpi ${feature?'featured':''}"><div class="label">${label}</div><div class="value num">${value}</div><div class="foot">${foot}</div></div>`}
const acts=['Leads trabalhados','Ligações','Pessoas faladas','Qualificados','Agendamentos','Visitas','Propostas','Vendas'];const barcolors=['#34845d','#b9964f','#677ea1','#9a729c','#7a9e51','#8b81a9','#559b9e','#466151'];
function activity(){const vals=state.role==='broker'?[60,110,34,18,10,6,3,1]:[360,720,161,70,38,24,12,4];return `<div class="panel"><div class="panelhead"><div><h2>Funil de atividades</h2><p>Produção no período · pessoas e ações registradas</p></div>${chip('Atividade')}</div><div class="funnelbars">${acts.map((a,i)=>`<div class="barrow"><span>${a}</span><div class="bartrack"><div class="bar" style="width:${Math.max(7,vals[i]/Math.max(...vals)*100)}%;background:${barcolors[i]}">${vals[i]}</div></div><small>${i?((vals[i]/vals[0])*100).toFixed(0)+'%':'base'}</small></div>`).join('')}</div><p class="muted" style="font-size:9px;margin-top:17px">As barras registram volume de trabalho. A conversão comercial está no funil em cone.</p></div>`}
function chart(){return `<div class="panel"><div class="panelhead"><div><h2>Ritmo da operação</h2><p>Atividades registradas nos últimos 14 dias</p></div>${chip('14 dias')}</div><div class="monthchart">${Array.from({length:14},(_,i)=>`<div class="daycol"><div class="stack" style="height:${[40,57,73,52,90,70,30,67,92,61,105,79,51,86][i]}%">${barcolors.slice(0,6).map((c,j)=>`<i style="background:${c};height:${[30,18,22,14,9,7][j]}%"></i>`).join('')}</div><span>${String(i+28>31?i-3:i+28).padStart(2,'0')}</span></div>`).join('')}</div><div class="chartlegend">${acts.slice(0,6).map((a,i)=>`<span><i class="swatch" style="--c:${barcolors[i]}"></i>${a}</span>`).join('')}</div></div>`}
function goals(){const labels=[...acts,'VGV'];let real=[360,720,161,70,38,24,12,4,2400000],targets=[600,1200,200,80,40,28,18,6,3500000];if(state.role==='broker'){real=[60,110,34,18,10,6,3,1,625000];targets=[120,240,48,24,14,8,6,3,1000000]}return `<div class="panel"><div class="panelhead"><div><h2>Metas do período</h2><p>O caminho entre o trabalho de hoje e o resultado do mês</p></div>${state.role==='manager'?btn(icon('settings')+' Configurar metas','metas','tiny'):chip('Definidas pela gestão')}</div><div class="goals">${labels.map((a,i)=>{const target=state.settings?.['meta-'+i]||targets[i],r=real[i],pct=Math.round(r/target*100);return `<div class="goal"><div class="top"><span>${a}</span><b class="${pct>=100?'up':'down'}">${pct}%</b></div><strong class="num">${i===8?money(target):target}</strong><small>Feito ${i===8?money(r):r} · Falta ${i===8?money(Math.max(0,target-r)):Math.max(0,target-r)}</small><div class="progress"><i style="width:${Math.min(pct,100)}%"></i></div></div>`}).join('')}</div></div>`}
function dashboard(){return `${head(state.role==='manager'?'Sua operação, em perspectiva.':'Seu próximo resultado começa aqui.',state.role==='manager'?'Terça-feira, 10 de novembro · uma visão clara do que move suas vendas.':'Blanca, acompanhe seu trabalho e as próximas oportunidades.',btn(icon('download')+' Relatório','export')+btn(icon('plus')+' Novo lead','newlead','primary'))}${filters()}<div class="welcome"><span><b>${state.role==='manager'?'3 oportunidades aguardam captura':'4 clientes aguardam sua resposta'}</b> · ${state.role==='manager'?'Somente na etapa NOVO do funil principal':'Dê continuidade aos atendimentos de hoje'}</span><button class="btn tiny" data-route="${state.role==='manager'?'catraca':'atender'}">Ver agora ${icon('arrow')}</button></div><div class="grid cols4">${kpi('VGV no período',state.role==='manager'?'R$ 2.400.000':'R$ 625.000',state.role==='manager'?'68,6% da meta mensal':'62,5% da meta mensal',true)}${kpi('Vendas realizadas',state.role==='manager'?'4':'1','Contratos registrados no mês')}${kpi('Atendimentos qualificados',state.role==='manager'?'70':'18','Clientes que avançaram no comercial')}${kpi('Visitas realizadas',state.role==='manager'?'24':'6','Agendamento e visita são separados')}</div><div class="dashrow">${goals()}<div class="panel"><div class="panelhead"><div><h2>Próximos passos</h2><p>Prioridades para dar continuidade</p></div>${chip('Hoje','gold')}</div>${[[0,'Enviar simulação da unidade','10h30'],[2,'Confirmar a videochamada','14h00'],[3,'Retornar sobre a proposta','16h00'],[4,'Acompanhar a documentação','17h30']].filter(t=>state.role==='manager'||leads[t[0]].owner==='Blanca').map((t,i)=>`<div class="taskrow"><button class="taskcheck" data-action="taskdone" aria-label="Concluir tarefa"></button><div><strong><button class="link" style="background:none;padding:0;color:inherit" data-lead="${t[0]}">${leads[t[0]].name}</button></strong><p>${t[1]}</p></div><span class="time">${t[2]}</span></div>`).join('')}<div class="spacer"></div><div class="subtle">Cada próximo passo tem um responsável e uma data. Nenhum lead fica para trás.</div><div class="spacer"></div>${btn('Ver atendimentos '+icon('arrow'),'goto-atender','primary')}</div></div><div class="dashrow">${activity()}${chart()}</div>`}
function cone(individual=false){const nums=individual?[60,18,10,6,3,1]:[161,70,38,24,12,4];const thresholds=[0,40,50,60,40,50],cumtarget=[100,40,20,12,4.8,2.4];return `<div class="panel"><div class="panelhead"><div><h2>Funil de conversão ${individual?'individual':'da operação'}</h2><p>Passagens por etapa no período · ${individual?state.person:'funil principal'}</p></div>${chip('Conversão')}</div><div style="display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:20px;margin-bottom:12px;font-size:9px;color:#84927a"><span>CHEGARAM À ETAPA</span><span>ETAPA ANTERIOR</span><span>DESDE A ENTRADA</span></div><div class="conearea"><div class="conelabels">${stages.map((a,i)=>`<div class="coneslice" style="width:${100-i*11}%;background:${['#1e5c3f','#2c714b','#4b8156','#6a8b57','#8f925b','#b59b5a'][i]}"><span>${a}</span><b class="num">${nums[i]}</b></div>`).join('')}</div><div class="rates">${nums.map((n,i)=>{let pct=i?n/nums[i-1]*100:0;return `<div><strong class="num ${i?(pct>=thresholds[i]?'up':'down'):'muted'}">${i?pct.toFixed(1).replace('.',',')+'%':'—'}</strong><small>${i?n+' de '+nums[i-1]+' · meta '+thresholds[i]+'%':'início do funil'}</small></div>`}).join('')}</div><div class="rates">${nums.map((n,i)=>{let pct=n/nums[0]*100;return `<div><strong class="num ${pct>=cumtarget[i]?'up':'down'}">${pct.toFixed(1).replace('.',',')}%</strong><small>${i?'meta '+cumtarget[i]+'%':nums[0]+' leads na base'}</small></div>`}).join('')}</div></div><p style="font-size:9px;margin-top:20px;color:#8a967e">Metas ilustrativas: <span class="up">verde dentro</span> · <span class="down">vermelho abaixo</span>. Cada coluna usa sua base e sua meta. Sem meta/base: neutro.</p></div>`}
function wallet(individual=false){return `<div class="panel"><div class="panelhead"><div><h2>${individual?'Onde estão os leads de '+state.person+' agora':'Carteira atual por etapa'}</h2><p>Fotografia da carteira atual · não é conversão do período</p></div>${chip('Carteira')}</div><div class="donut-layout"><div class="donut"><div class="center"><strong class="num">428</strong><small>contatos agora</small></div></div><div class="legend">${[['Atendimento Frio',279,'65,2%','#277254'],['Compra Futura',53,'12,4%','#173b41'],['Lead',42,'9,8%','#759357'],['Atendimento Qualificado',34,'7,9%','#a2b566'],['Inbox',7,'1,6%','#d2b673'],['Venda',5,'1,2%','#ad6945'],['Outras 3 etapas',8,'1,9%','#b3bbb0']].map(a=>`<div><i class="swatch" style="--c:${a[3]}"></i><span>${a[0]}</span><b>${a[1]}</b><small>${a[2]}</small></div>`).join('')}</div></div></div>`}
function sdr(){return `<div class="panel"><div class="panelhead"><div><h2>Indicadores do SDR</h2><p>SDR humano, bot e IA consolidados · apenas quem passou pelo funil SDR</p></div>${chip('Pré-atendimento')}</div><div class="sdrstats">${[['Chegaram à fila','16','etapa Lead Novo'],['Atendidos','9','no funil SDR'],['1ª resposta','1 min','mediana'],['Responderam','8','88,9% · 8 de 9'],['Pré-qualificados','3','33,3% · 3 de 9'],['Roleta / corretor','3','33,3% · 3 de 9'],['Perdidos','0','no período']].map(a=>kpi(...a)).join('')}</div><div class="spacer"></div><div class="tablewrap"><table class="table"><thead><tr>${['Origem','Recebidos','Atendidos','Responderam','SDR → principal'].map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${[['Meta Ads',11,4,3,2],['WhatsApp',3,3,3,1],['Cadastro / importação',2,2,2,0]].map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div><p class="muted" style="font-size:9px;margin-top:13px">Pré-qualificado exige mudança de funil SDR → principal. Trocar proprietário no SDR ou IA conversar só no principal não qualifica. Taxas desta ilustração: sobre 9 atendidos.</p></div>`}
function personSelector(){return `<div class="personrow">${people.map((p,i)=>`<button class="personbtn ${state.person===p?'active':''}" data-person="${p}"><span class="avatar">${p.slice(0,2).toUpperCase()}</span>${p}</button>`).join('')}</div>`}
function individual(){return `<div class="panel"><div class="panelhead"><div><h2>Leads recebidos por dia</h2><p>Distribuição por captura no período selecionado</p></div><input type="date" value="2026-11-10" data-field="reportday" aria-label="Dia" style="padding:7px;border:1px solid #dae4d2;border-radius:5px"></div><div class="subtle" style="display:flex;justify-content:space-between"><span>Terça-feira, 10 de novembro · ${state.person}</span><strong>5 recebidos</strong></div></div><div class="spacer"></div><div class="panel"><div class="panelhead" style="margin:0"><div style="display:flex;align-items:center;gap:12px"><span class="avatar">${state.person.slice(0,2).toUpperCase()}</span><div><h2>${state.person} · relatório individual</h2><p>Indicadores do corretor no período selecionado</p></div></div><div class="actions">${state.role==='manager'?btn(icon('settings')+' Indicadores do resumo','individualconfig','tiny'):''}${btn(icon('download')+' Relatório para reunião','export','tiny')}</div></div></div><div class="spacer"></div><div class="grid cols4">${(state.individualMetrics||['Recebidos','Qualificados','Agendamentos','Visitas','Propostas','Vendas']).map(m=>kpi(m,({'Recebidos':60,'Qualificados':18,'Agendamentos':10,'Visitas':6,'Propostas':3,'Vendas':1,'1ª resposta':'1 min','Fluidez no Atendimento':'2 min','Ligações':110,'Leads trabalhados':60,'Mensagens':130,'Pessoas faladas':34,'Na mão':428,'Tarefas criadas':22,'Tarefas feitas':20,'Leads atrasados':2,'Perdidos':4})[m]??'—','no período selecionado')).join('')}</div><div class="spacer"></div>${cone(true)}<div class="spacer"></div>${wallet(true)}`}
function calcScore(i){let q=state.settings?.Score||{};return Math.max(0,Math.round((18-i*2)*Number(q['qualificado-pontos-']||1)+(10-i)*Number(q['agendamento-pontos-']||2)+(6-i)*Number(q['visita-pontos-']||3)+Math.max(0,3-i)*Number(q['proposta-pontos-']||5)+Math.max(0,1-i)*Number(q['venda-pontos-']||10)-2*Number(q['retirada-por-atraso']||1)))}
function score(){let selected=state.scoreCols||['Score','Conversão','Recebidos','1ª resposta','Ligações','Qualificados','Agendamentos','Visitas','Vendas'];const vals=[72,'6,7%',60,'1 min','2 min',110,60,130,34,18,10,6,3,1,428,22,20,2,4];return `<div class="panel"><div class="panelhead"><div><h2>Score de performance + Equipe</h2><p>Atividades, resultado e acompanhamento em uma visão única</p></div>${btn(icon('settings')+' Configurar Score','scoreconfig','primary tiny')}</div><div class="tablewrap"><table class="table"><thead><tr><th>#</th><th>Corretor</th>${selected.map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${people.filter(p=>(state.scoreParticipants||['Blanca','Sil','Veronica','Ezequiel','Nádia']).includes(p)).map((p,i)=>`<tr><td class="rank">${i+1}</td><td><button class="link" data-person="${p}">${p}</button></td>${selected.map((m,j)=>`<td ${m==='Score'?'class="rank"':''}>${m==='Score'?calcScore(i):typeof vals[metrics.indexOf(m)]==='number'?Math.max(0,vals[metrics.indexOf(m)]-i*(j%3+1)):vals[metrics.indexOf(m)]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p style="font-size:9px;color:#88947d;margin-top:14px">${selected.length} de 19 indicadores visíveis · clique no corretor para selecionar seu relatório individual.</p></div>`}
function reports(){return head('Relatórios que orientam decisões.','Pré-atendimento, equipe e resultado individual no mesmo lugar.',btn(icon('download')+' Exportar relatório','export'))+filters()+sdr()+'<div class="spacer"></div>'+score()+'<div class="spacer"></div><div class="eyebrow" style="margin-bottom:12px">RELATÓRIO INDIVIDUAL</div>'+personSelector()+individual()}
function operation(){const tab=state.tab||'Funil';return head('Visão geral da operação','Entenda o avanço comercial e a origem das suas oportunidades.')+filters()+`<div class="grid cols3">${kpi('Leads recebidos','360','no período selecionado')}${kpi('1ª resposta','4 min','mediana no comercial')}${kpi('Responderam','46,2%','da população contatada')}</div><div class="spacer"></div>`+tabs(['Funil','Campanhas'],tab)+(tab==='Funil'?cone()+ '<div class="spacer"></div>'+wallet():campaigns())}
function campaigns(){return `<div class="panel"><div class="panelhead"><div><h2>Desempenho dos anúncios</h2><p>Meta Ads · investimento e resultado comercial por campanha</p></div>${btn('Atualizar da Meta','refresh','tiny')}</div><div class="grid cols4">${kpi('Investimento','R$ 3.420','dados ilustrativos')}${kpi('Leads na Meta','180','conversões da plataforma')}${kpi('Leads no CRM','171','entradas identificadas')}${kpi('Custo por qualificado','R$ 81','42 qualificados comerciais')}</div><div class="spacer"></div><div class="tablewrap"><table class="table"><thead><tr>${['Campanha','Investimento','Leads Meta','Leads CRM','Qualificados','Vendas','VGV'].map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${[['Antunes | Investimento','R$ 1.420',78,74,19,2,'R$ 1.250.000'],['Croas | Lotes','R$ 1.100',61,59,15,1,'R$ 160.000'],['Villa Camboa | Frente-mar','R$ 900',41,38,8,1,'R$ 540.000']].map(a=>'<tr>'+a.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div></div><div class="spacer"></div><div class="panel"><div class="panelhead"><div><h2>Campanhas e origem</h2><p>Qualificado comercial = passagem em Atendimento Qualificado</p></div></div><div class="tablewrap"><table class="table"><thead><tr><th>Origem</th><th>Leads</th><th>Qualificados</th><th>Taxa</th><th>Vendas</th></tr></thead><tbody>${[['Meta Ads',171,42,'24,6%',4],['WhatsApp',98,18,'18,4%',0],['Site',63,7,'11,1%',0],['Portais',28,3,'10,7%',0]].map(a=>'<tr>'+a.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div></div>`}
function kanban(){let cols=['NOVO',...stages.slice(0,1),'Atendimento Frio',...stages.slice(1),'Repique 30D','Compra Futura','Perdido'];return head('Cada oportunidade, no seu próximo passo.','Funil comercial com filtros visíveis e uma ficha completa em cada lead.',btn(icon('plus')+' Novo lead','newlead','primary'))+`<div class="filters"><input class="search" placeholder="Buscar lead, produto ou corretor" id="kanbansearch" aria-label="Buscar lead"><select aria-label="Funil" id="funilselect"><option>Braço Externo · Principal</option><option>SDR / Pré-atendimento</option></select>${state.role==='manager'?`<select id="ownerfilter" aria-label="Corretor"><option value="">Toda a equipe</option>${people.map(p=>'<option>'+p+'</option>').join('')}</select>`:''}<select aria-label="Temperatura" id="tempfilter"><option value="">Temperatura</option><option>Quente</option><option>Morno</option><option>Frio</option></select><select aria-label="Origem" id="originfilter"><option value="">Origem</option><option>Meta Ads</option><option>WhatsApp</option><option>Site</option><option>Portal</option></select>${btn('Filtros avançados','filters','tiny')}</div><div class="kanban" id="board">${cols.map((col,i)=>`<div class="column" data-stage="${col}" ondragover="event.preventDefault()"><div class="columnhead"><i class="swatch" style="--c:${barcolors[i%8]}"></i>${col}<small>${leads.filter(l=>l.stage===col).length}</small></div>${leads.map((l,j)=>l.stage===col&&(state.role==='manager'||l.owner==='Blanca')?leadCard(l,j):'').join('')}<button class="btn tiny" data-action="newlead" style="width:100%;margin-top:4px;background:transparent">+ Adicionar lead</button></div>`).join('')}</div>`}
function leadCard(l,i){return `<article class="leadcard" draggable="true" data-lead="${i}" data-owner="${l.owner}" data-temp="${l.temp}" data-origin="${l.origin}"><div class="title">${esc(l.name)}</div><p>Contato · •••• 4821</p><p>Última interação há 2h</p>${chip(l.temp,l.temp==='Quente'?'gold':'')}${chip(l.origin,'blue')}<p style="margin-top:10px;color:#4e7554">${esc(l.product)}</p><div class="who"><span class="avatar" style="width:20px;height:20px;font-size:7px">${l.owner.slice(0,2)}</span>${l.owner}</div></article>`}
function attending(){const l=leads[state.chat];return head('Atendimento com contexto.','Conversa, ficha e próximo passo, sem sair do atendimento.')+`<div class="filters"><input class="search" placeholder="Buscar por nome ou telefone" aria-label="Buscar conversa" data-chatsearch><select aria-label="Status"><option>Todas as conversas</option><option>Aguardando resposta</option><option>Em atendimento</option><option>Novos contatos</option><option>Finalizados</option></select>${btn('Filtrar por equipe, etapa e canal','filters','tiny')}</div><div class="conversation"><div class="chatlist"><div style="padding:14px;border-bottom:1px solid var(--line)">${chip('4 aguardando','gold')} ${chip('Meu WhatsApp')}</div>${leads.filter(a=>state.role==='manager'||a.owner==='Blanca').map(a=>{let i=leads.indexOf(a);return `<div class="chatitem ${state.chat===i?'active':''}" data-chat="${i}"><div style="display:flex;gap:8px;align-items:center"><span class="avatar">${a.initials}</span><strong style="font-size:11px">${a.name}</strong></div><p>${a.note.slice(0,40)}…</p><p>${chip(a.stage)} <span>${a.owner}</span></p></div>`}).join('')}</div><div class="chatroom"><div class="chatheader"><span class="avatar">${l.initials}</span><div><strong>${l.name}</strong><p style="font-size:9px;color:#87957d">${l.product} · ${l.origin}</p></div><div class="actions" style="margin-left:auto">${btn('Abrir ficha','openchatlead','tiny')}${btn('Finalizar','finishchat','tiny')}</div></div><div class="bubbles"><div style="text-align:center;font-size:9px;color:#8c9982">Hoje · 10 de novembro</div><div class="bubble">Olá, gostaria de conhecer as opções de ${l.product}.<small>09:42</small></div><div class="bubble sent">Olá, ${l.name.split(' ')[0]}! Vou te ajudar a encontrar a melhor opção. Você busca um imóvel para usar ou para investir?<small>09:43 · ✓✓</small></div><div class="bubble">Quero usar com a minha família e também gerar renda quando não estivermos.<small>09:45</small></div><div class="bubble sent">Entendi. Tenho uma opção que atende a esses dois objetivos. Qual faixa de investimento você considera?<small>09:46 · ✓✓</small></div>${(state.messages||[]).filter(m=>m.lead===state.chat).map(m=>`<div class="bubble sent">${esc(m.text)}<small>agora · demonstração</small></div>`).join('')}</div><form class="composer" id="chatform"><button type="button" class="iconbtn" data-action="attach" aria-label="Anexar arquivo">${icon('plus')}</button><button type="button" class="iconbtn" data-action="record" aria-label="Gravar áudio">${icon('mic')}</button><input name="message" placeholder="Escreva sua mensagem…" autocomplete="off" required><button class="btn primary" type="submit">Enviar ${icon('arrow')}</button></form></div><aside class="chatinfo"><div style="display:flex;align-items:center;gap:8px"><span class="avatar">${l.initials}</span><strong>${l.name}</strong></div><label>ETAPA DO FUNIL</label><select data-leadstage="${state.chat}">${['NOVO',...stages,'Atendimento Frio'].map(x=>`<option ${x===l.stage?'selected':''}>${x}</option>`).join('')}</select><div class="toggleline"><span>Autoatendimento IA</span><button class="switch ${state.aiOff?'':'on'}" data-action="aitoggle" aria-label="Alternar IA"></button></div><div class="spacer"></div>${btn('Resumo da conversa','summary','tiny')}<label>RESPONSÁVEL</label><select data-ownerlead="${state.chat}" ${state.role==='broker'?'disabled':''}>${people.map(p=>`<option ${p===l.owner?'selected':''}>${p}</option>`).join('')}</select><label>IMÓVEL DE INTERESSE</label><p style="font-size:11px;margin-top:8px">${l.product}</p><label>PERFIL DE BUSCA</label><p style="font-size:10px;margin-top:8px;color:#6c825f">Uso da família + renda<br/>Faixa: ${money(l.budget)}</p><label>TAREFAS E PRÓXIMO PASSO</label><div class="spacer"></div>${btn('+ Marcar tarefa','newtask','tiny')}<div class="spacer"></div>${btn('Ficha completa '+icon('arrow'),'openchatlead','primary tiny')}</aside></div>`}
const roulettes=['Catraca principal','Antunes Beach Resort','Croas de São Bento','Villa Camboa','Horizon','Mirante de Maragogi'];
function roulette(){const tab=state.tab||'Visão geral';return head('Distribuição sob controle.','Catracas por canal, imóvel, anúncio e time.',btn(icon('plus')+' Criar catraca','newroulette','primary'))+tabs(['Visão geral','Catraca principal',...roulettes.slice(1)],tab)+(tab==='Visão geral'?`<div class="grid cols3">${kpi('Aguardando captura','3','Somente NOVO do principal')}${kpi('Corretores disponíveis','4 de 9','prontidão da equipe')}${kpi('Catracas ativas','6','times e origens configurados')}</div><div class="spacer"></div><div class="grid cols2">${roulettes.map((r,i)=>`<div class="panel"><div class="panelhead"><div><h2>${r}</h2><p>${i?'Time Litoral · funil principal / NOVO':'Recebe origens sem regra específica'}</p></div>${chip('Ativa')}</div><p style="font-size:11px;color:#859778">${i?'Site por código de imóvel + formulário Meta selecionado':'Todos os canais sem correspondência específica'}</p><div class="personrow" style="margin:12px 0 0">${people.slice(0,4).map(p=>`<span class="chip">${p}</span>`).join('')}</div><div class="actions">${btn('Abrir catraca','roulettetab','tiny',`data-value="${r}"`)}${btn('Configurar','editroulette','tiny',`data-value="${r}"`)}${btn('Relatório','roulettereport','tiny',`data-value="${r}"`)}</div></div>`).join('')}</div>`:rouletteDetail(tab))}
function rouletteDetail(name){return `<div class="grid cols3">${kpi('Catraca selecionada',name==='Catraca principal'?'Principal':name,'Regra de destino: Braço Externo / NOVO')}${kpi('Esperando corretor','3','exclui SDR e já capturados')}${kpi('Próximo da vez','Blanca','entre os participantes disponíveis')}</div><div class="spacer"></div><div class="panel"><div class="panelhead"><div><h2>Disponibilidade da equipe</h2><p>Participantes vinculados à Gerência Litoral · seleção por equipe ou individual</p></div>${btn('Editar participantes e origens','editroulette','primary tiny',`data-value="${name}"`)}</div><div class="personrow">${people.map((p,i)=>`<button class="personbtn" data-action="availability-person"><span class="avatar">${p.slice(0,2)}</span>${p}<span class="switch ${i%3===0?'':'on'}"></span></button>`).join('')}</div></div><div class="spacer"></div><div class="panel"><div class="panelhead"><div><h2>Leads aguardando captura</h2><p>Depois de capturado, o lead deixa de estar na fila.</p></div>${btn('Relatório desta catraca','roulettereport','tiny',`data-value="${name}"`)}</div>${['Sofia Mendes','Ana Carvalho','Guilherme Souza'].map((n,i)=>`<div class="rule"><div><strong>${n}</strong><p>NOVO · Braço Externo · ${i?i*3:2} min na fila</p></div><div class="actions">${chip(['Site · Imóvel ABR-034','WhatsApp · final 6529','Portal · anúncio 7812'][i])}${btn('Capturar para Blanca','capture','primary tiny')}</div></div>`).join('')}</div>`}
function propertyCard(p,i){return `<article class="property"><img src="${p.img}" alt="Imagem ilustrativa de ${esc(p.name)}"><div class="body">${chip(p.type)}<h3>${esc(p.name)}</h3><p>${esc(p.location)}</p><p style="margin-top:8px">${p.area} m² ${p.rooms?' · '+p.rooms+' quarto(s) · 1 vaga':''}</p><div class="price num">${money(p.price)}</div><div class="bottom">${chip('Disponível')}${btn('Abrir imóvel '+icon('arrow'),'property','tiny',`data-index="${i}"`)}</div></div></article>`}
function catalog(){return head('O imóvel certo, com a informação certa.','Catálogo conectado à ficha do lead, ao site e aos portais.',(state.role==='manager'?btn('Portais','portals')+btn(icon('plus')+' Cadastrar imóvel','newproperty','primary'):btn('Simulação completa','simulation','primary')))+`<div class="filters"><input class="search" id="propertysearch" placeholder="Buscar imóvel por nome, código ou cidade" aria-label="Buscar imóvel"><select id="propertytype" aria-label="Tipo de imóvel"><option value="">Todos os tipos</option>${['Casa','Empreendimento','Imóvel pronto','Loteamento','Terreno'].map(t=>'<option>'+t+'</option>').join('')}</select><select aria-label="Finalidade"><option>Venda e locação</option><option>Venda</option><option>Locação</option></select>${btn('Mais filtros','propertyfilters','tiny')}</div><div class="propertygrid" id="propertygrid">${properties.map(propertyCard).join('')}</div>`}
function sitesPage(){const tab=state.tab||'Modelos';return head('Seu site, conectado à sua operação.','Cetrolab · catálogo, conteúdo e identidade do site público.',btn('Prévia do site','sitepreview')+btn('Publicar alterações','publishdemo','primary'))+`<div class="connection"><span class="avatar">${icon('globe')}</span><div><strong>Site da imobiliária</strong><p style="font-size:10px;color:#87997c">vjimoveis.exemplo.com.br · endereço ilustrativo</p></div><span class="actions">${chip('No ar')} ${btn('Configurar domínio','site-domain','tiny')}</span></div><div class="spacer"></div>`+tabs(['Modelos','Conteúdo','Endereço e Pixel','Domínio próprio','SEO e Google'],tab)+(tab==='Modelos'?`<div class="grid cols2">${['Institucional','Editorial','Lançamento','Bairros'].map((m,i)=>`<div class="panel"><div style="background:${i%2?'#152f26':'#e9eee0'};height:145px;border-radius:7px;padding:18px;margin-bottom:17px;position:relative;overflow:hidden"><span style="font:800 12px Manrope;color:${i%2?'#e4d3a1':'#4e6541'}">VJ IMÓVEIS</span><div style="margin-top:20px;width:70%;height:9px;background:${i%2?'#c5b689':'#6f8b5c'};border-radius:3px"></div><div style="margin-top:8px;width:50%;height:6px;background:#8eac762b;border-radius:3px"></div><div style="display:flex;gap:8px;margin-top:20px">${[1,2,3].map(()=>'<div style="height:39px;width:70px;background:#77985a29;border-radius:4px"></div>').join('')}</div></div><div class="panelhead"><div><h2>${m}</h2><p>${['Conteúdo institucional e catálogo completo','Fotografia e tipografia em destaque','Página focada em um empreendimento','Busca por região e perfil de imóvel'][i]}</p></div></div><div class="actions">${btn('Ver prévia','sitepreview','tiny',`data-value="${m}"`)}${btn('Usar modelo','selectmodel','primary tiny',`data-value="${m}"`)}</div></div>`).join('')}</div>`:siteForm(tab))}
function siteForm(tab){let f=tab==='Conteúdo'?[field('Sobre a imobiliária','textarea','Uma imobiliária que conecta pessoas às melhores oportunidades no litoral.'),field('Instagram','text','@vjimoveisbrasil'),field('Facebook','text','VJ Imóveis Brasil'),field('Equipe no site','select','Blanca',['Blanca','Sil','Veronica','Todos']),field('Depoimentos','textarea','Cadastre os depoimentos autorizados de seus clientes.')]:tab==='Endereço e Pixel'?[field('Endereço do site','text','vjimoveis'),field('WhatsApp do site','tel','(82) 90000-0000'),field('Frase de apresentação','text','Seu próximo imóvel, com segurança.'),field('Pixel do Meta','text','ID do Pixel')]:tab==='Domínio próprio'?[field('Domínio','text','www.suaimobiliaria.com.br'),'<div class="subtle full">Adicione o domínio e consulte as orientações de DNS. No protótipo, a validação é demonstrativa.</div>']:[field('Nome da marca no site','text','VJ Imóveis'),field('Título SEO','text','VJ Imóveis | Imóveis em Maragogi e Japaratinga'),field('Descrição','textarea','Conheça imóveis e empreendimentos no litoral de Alagoas.'),field('Google Tag Manager','text','GTM-EXEMPLO'),field('Verificação Search Console','text','Código de verificação'),field('Sitemap','text','/sitemap.xml')];return `<form class="panel demoform" data-save="${tab}"><div class="panelhead"><h2>${tab}</h2></div><div class="formgrid">${f.join('')}</div><div class="formfooter">${btn('Salvar alterações','submit','primary')}</div></form>`}
function shifts(){return head(state.role==='manager'?'Plantões por time.':'Sua escala de plantão.','Distribua presença e oportunidades com clareza.',state.role==='manager'?btn('Escolher planilha','uploadscale')+btn(icon('plus')+' Configurar plantão','newshift','primary'):'')+filters(`<select aria-label="Time do plantão"><option>Time Litoral</option><option>Time Capital</option></select>`)+`<div class="panel"><div class="panelhead"><h2>Novembro de 2026</h2><div class="segmented"><button class="active" data-action="calview" data-value="Mês">Mês</button><button data-action="calview" data-value="Semana">Semana</button><button data-action="calview" data-value="Dia">Dia</button></div></div><div class="calendar">${Array.from({length:21},(_,i)=>`<div class="calday"><b>${String(i+1).padStart(2,'0')}/11</b><p style="font-size:8px;color:#97a18a">${['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][i%7]}</p><button class="shift" data-action="editshift" data-value="${i+1}/11">Manhã · ${people[i%9]}</button><button class="shift" data-action="editshift" data-value="${i+1}/11">Tarde · ${people[(i+3)%9]}</button></div>`).join('')}</div></div>`}
function team(){const tab=state.tab||'Estrutura';return head('Pessoas alinhadas. Acessos claros.','Diretoria → Gerência → Subgerência opcional → Corretor.',btn('Convidar usuário','invite')+btn(icon('plus')+' Criar equipe','newteam','primary'))+tabs(['Estrutura','Pessoas','Permissões','Disponibilidade'],tab)+(tab==='Estrutura'?`<div class="grid cols2"><div class="panel"><div class="panelhead"><div><h2>Estrutura da operação</h2><p>Monte equipes e use os mesmos vínculos em relatórios, roletas e plantões</p></div></div><div class="treeline">${icon('users').replace('<svg','<svg width="20" height="20"')}<strong>Diretoria Comercial</strong>${btn('Editar','editteam','tiny',`data-value="Diretoria Comercial"`)}</div><div class="treebranch"><div class="treeline"><strong>Gerência Litoral</strong>${btn('Acessos','permissions','tiny')}</div><div class="treebranch"><div class="treeline">Subgerência Norte ${chip('Opcional')}</div><div class="treebranch">${['Blanca','Sil','Veronica'].map(p=>`<div class="treeline"><span class="avatar">${p.slice(0,2)}</span>${p}${chip('Corretor')}</div>`).join('')}</div></div><div class="treeline"><strong>Gerência Capital</strong>${btn('Editar','editteam','tiny')}</div><div class="treebranch"><div class="treeline"><span class="avatar">EZ</span>Ezequiel · Corretor</div></div></div></div><div class="panel"><div class="panelhead"><h2>Um time, em toda a operação</h2></div><ul class="featurelist"><li>Relatórios filtrados pela hierarquia e pelo acesso de cada pessoa.</li><li>Vincule uma diretoria ou gerência à catraca para carregar seus corretores.</li><li>Plantões separados por times, com responsáveis e turnos.</li><li>Permissões de consultar números separadas das permissões de criar roletas.</li><li>Histórico preservado quando alguém muda de time.</li><li>Corretor básico acessa somente a própria carteira e as ferramentas autorizadas.</li></ul>${btn('Configurar permissões','permissions','primary')}</div></div>`:tab==='Pessoas'?`<div class="grid cols3">${people.map((p,i)=>`<div class="teamcard"><div class="top"><span class="avatar">${p.slice(0,2)}</span><div><h3>${p}</h3><p class="muted" style="font-size:10px">Corretor · Gerência ${i%3?'Litoral':'Capital'}</p></div></div>${chip('Ativo')}${chip('Acesso básico','gold')}<div class="spacer"></div><div class="actions">${btn('Permissões','permissions','tiny',`data-value="${p}"`)}${btn('Mover de equipe','editteam','tiny',`data-value="${p}"`)}</div></div>`).join('')}</div>`:tab==='Permissões'?permissionsForm():availability(true))}
function permissionsForm(){return `<form class="panel demoform" data-save="Permissões"><div class="panelhead"><h2>Matriz de permissões</h2>${chip('Gerente Litoral')}</div><div class="formgrid">${field('Função','select','Gerente',['Diretoria','Gerente','Subgerente','Corretor'])}${field('Escopo','select','Gerência Litoral',['Operação inteira','Diretoria Comercial','Gerência Litoral','Subgerência Norte','Carteira própria'])}</div><div class="tablewrap"><table class="table"><thead><tr><th>Área / ferramenta</th>${['Consultar','Criar','Editar','Excluir','Exportar'].map(t=>'<th>'+t+'</th>').join('')}</tr></thead><tbody>${['Painel e indicadores','Relatórios e score','Funil e ficha do lead','Catracas / roletas','Imóveis e catálogo','Cetrolab / site','Plantão','Marketing e fluxos','Base de leads','Equipe e acessos','Configurações'].map((t,i)=>`<tr><td>${t}</td>${Array.from({length:5},(_,j)=>`<td><input aria-label="${t}: ${['Consultar','Criar','Editar','Excluir','Exportar'][j]}" type="checkbox" class="permit" ${i<5&&j<3?'checked':''} name="perm-${i}-${j}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="spacer"></div><div class="subtle">As permissões sempre respeitam o escopo. Filtrar outra gerência, exportar ou abrir um detalhe não amplia o acesso.</div><div class="formfooter">${btn('Salvar permissões','submit','primary')}</div></form>`}
function availability(manager=false){return `${manager?'':head('Sua disponibilidade, de forma simples.','Só participa da distribuição quem está disponível no dia.')}<div class="grid ${manager?'cols2':''}" style="${manager?'':'max-width:650px;margin:auto'}"><div class="panel"><div class="panelhead"><h2>${manager?'Prontidão da equipe':'Você está '+(state.available?'disponível':'indisponível')+' hoje'}</h2><span class="switch ${state.available?'on':''}" data-action="available" role="switch" aria-checked="${state.available}" tabindex="0"></span></div><p class="muted">${state.available?'Sua disponibilidade está ativa para participar das catracas vinculadas.':'Você está fora do rodízio de distribuição até ficar disponível novamente.'}</p><div class="spacer"></div>${btn(state.available?'Ficar indisponível':'Ficar disponível','available',state.available?'':'primary')}<div class="spacer"></div><div class="subtle">A disponibilidade define quem pode receber o próximo lead. Ela não altera a propriedade dos leads já capturados.</div></div><div class="panel"><div class="panelhead"><h2>${manager?'Disponibilidade por pessoa':'Seus últimos 7 dias'}</h2></div>${(manager?people.slice(0,6):['10/11 · 08h03','09/11 · 18h00','09/11 · 08h12','06/11 · 18h00']).map((p,i)=>`<div class="toggleline"><span>${p}</span>${manager?`<button class="switch ${i%3?'on':''}" data-action="togglegeneric" aria-label="Disponibilidade de ${p}"></button>`:chip(i%2?'Indisponível':'Disponível',i%2?'gold':'')}</div>`).join('')}</div></div>`}
function marketing(){const tab=state.tab||'Disparos';return head('Relacionamento em movimento.','Disparos organizados, contatos segmentados e envio com controle.',btn(icon('plus')+' Novo disparo','newblast','primary'))+tabs(['Disparos','Contatos','Configuração'],tab)+(tab==='Disparos'?`<div class="panel"><div class="panelhead"><h2>Seus disparos</h2>${chip('Demonstração')}</div><div class="tablewrap"><table class="table"><thead><tr><th>Nome</th><th>Público</th><th>Status</th><th>Enviados</th><th>Ações</th></tr></thead><tbody>${[['Retomada | Litoral','Qualificados', 'Agendado','0 / 42'],['Novidades | Antunes','Lista autorizada','Concluído','68 / 68']].map((a,i)=>`<tr><td><b>${a[0]}</b></td><td>${a[1]}</td><td>${chip(a[2],i?'':'gold')}</td><td>${a[3]}</td><td>${btn('Ver detalhes','blastdetail','tiny',`data-value="${a[0]}"`)}</td></tr>`).join('')}${(state.extras?.blasts||[]).map(n=>`<tr><td>${esc(n)}</td><td>Selecionado</td><td>${chip('Rascunho','gold')}</td><td>0</td><td>${btn('Abrir','blastdetail','tiny')}</td></tr>`).join('')}</tbody></table></div></div>`:tab==='Contatos'?`<div class="panel"><div class="panelhead"><div><h2>Listas de contatos</h2><p>Origem declarada e números organizados para segmentar o envio</p></div>${btn('Enviar lista de contatos','uploadcontacts','primary tiny')}</div><div class="rule"><div><h3>Clientes de lançamentos</h3><p>68 contatos · lista demonstrativa</p></div>${btn('Ver contatos','listcontacts','tiny')}</div></div><div class="spacer"></div><div class="panel"><div class="panelhead"><h2>Pedidos de saída</h2>${chip('2 bloqueados','gold')}</div><p class="muted">Quem pediu para sair não participa de novos disparos.</p><div class="spacer"></div><div class="actions"><input id="blocknumber" placeholder="Número para bloquear" style="padding:10px;border:1px solid #dce6d1;border-radius:6px">${btn('Bloquear número','blocknumber')}</div></div>`:`<form class="panel demoform" data-save="Configuração de disparos"><div class="panelhead"><h2>Ritmo e número de envio</h2></div><div class="formgrid">${field('Número de saída','select','WhatsApp da imobiliária',['WhatsApp da imobiliária','Número de contingência'])}${field('Limite por dia','number','150')}${field('Intervalo mínimo (segundos)','number','30')}${field('Intervalo máximo (segundos)','number','90')}${field('Horário inicial','time','09:00')}${field('Horário final','time','18:00')}</div><div class="subtle">As mensagens respeitam listas autorizadas, bloqueios e pedidos de saída. Esta apresentação simula o fluxo de configuração.</div><div class="formfooter">${btn('Salvar ritmo','submit','primary')}</div></form>`)}
