async function startRecording(el){if(!navigator.mediaDevices?.getUserMedia)return toast('Gravação indisponível neste navegador. Você pode anexar um áudio.');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];window.recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());el.classList.remove('recording');el.textContent='Gravar novamente';const blob=new Blob(chunks,{type:recorder.mimeType});const url=URL.createObjectURL(blob);let target=$('#audioresult');if(!target){target=document.createElement('div');target.id='audioresult';el.parentElement.after(target)}target.innerHTML=`<audio controls src="${url}" style="width:100%"></audio><a class="btn tiny" href="${url}" download="audio-cetro.webm">Baixar áudio gravado</a>`};recorder.start();el.classList.add('recording');el.textContent='● Gravando…';toast('Microfone ativo. Use Parar para concluir.')}catch(e){toast('Microfone não autorizado. Você pode anexar um áudio.')}}
function downloadCsv(){const rows=[['Lead','Origem','Funil','Etapa','Corretor','Imóvel'],...leads.filter(l=>state.role==='manager'||l.owner==='Blanca').map(l=>[l.name,l.origin,'Braço Externo',l.stage,l.owner,l.product])];const blob=new Blob(['\ufeff'+rows.map(a=>a.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(';')).join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='CETRO_Relatorio_Demonstrativo.csv';a.click();toast('Relatório demonstrativo exportado.');URL.revokeObjectURL(a.href)}
document.addEventListener('click',e=>{
 const route=e.target.closest('[data-route]');if(route){closeModal();go(route.dataset.route);return}
 const role=e.target.closest('[data-role]');if(role){state.role=role.dataset.role;state.person='Blanca';state.chat=0;localStorage.setItem('cetro-role',state.role);go('painel');toast(state.role==='manager'?'Visão da gestão: ferramentas e equipes.':'Visão do corretor: carteira própria e ferramentas básicas.');return}
 const tab=e.target.closest('[data-tab]');if(tab){go(state.route,tab.dataset.tab);return}
 const lt=e.target.closest('[data-leadtab]');if(lt){leadModal(state.selectedLead,lt.dataset.leadtab);return}
 const pt=e.target.closest('[data-propertytab]');if(pt){propertyModal(state.selectedProperty,pt.dataset.propertytab);return}
 const lead=e.target.closest('[data-lead]');if(lead){leadModal(Number(lead.dataset.lead));return}
 const chat=e.target.closest('[data-chat]');if(chat){state.chat=Number(chat.dataset.chat);shell();return}
 const person=e.target.closest('[data-person]');if(person){state.person=person.dataset.person;saveDemo();shell();if(state.route==='relatorios')$('.personrow').scrollIntoView({behavior:'smooth',block:'center'});return}
 const funnel=e.target.closest('[data-funnel]');if(funnel){state.currentFunnel=funnel.dataset.funnel;shell();return}
 const st=e.target.closest('[data-scoretab]');if(st){$('.modalbody').querySelectorAll('[data-scoretab]').forEach(b=>b.classList.toggle('active',b===st));let label=st.dataset.scoretab;const headings=$$('.modal h3');headings[label==='Pontuação'?2:0]?.scrollIntoView({behavior:'smooth',block:'center'});return}
 const a=e.target.closest('[data-action]');if(a){if(a.dataset.action==='submit')return;e.preventDefault();action(a.dataset.action,a)}
 if(e.target.classList.contains('modalback'))closeModal();
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.sidebar')?.classList.remove('open');closeModal()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="switch"]')){e.preventDefault();action(e.target.dataset.action,e.target)}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='chatform'){let text=new FormData(f).get('message');state.messages||=[];state.messages.push({lead:state.chat,text});shell();return}if(!f.classList.contains('demoform'))return;let vals=Object.fromEntries(new FormData(f));state.settings||={};state.settings[f.dataset.save]=vals;
 if(f.dataset.context==='score'){state.scoreCols=metrics.filter(m=>f.elements.namedItem('score-'+m)?.checked);state.scoreParticipants=people.filter(p=>f.elements.namedItem('person-'+p)?.checked)}
 if(f.dataset.context==='metas'){[...acts,'VGV'].forEach((a,i)=>{let key=a.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-');state.settings['meta-'+i]=Number(vals[key])})}
 if(f.dataset.context==='newlead'){let l={name:vals['nome-completo']||'Novo cliente',initials:'NC',owner:vals.corretor||'Blanca',origin:vals.origem||'Manual',stage:vals.etapa||'NOVO',product:properties[0].name,temp:'Frio',budget:500000,note:'Lead criado na demonstração.'};leads.push(l)}
 if(f.dataset.context==='blast'){state.extras||={};state.extras.blasts||=[];state.extras.blasts.push(vals['nome-do-disparo']||'Novo disparo')}
 if(f.dataset.context==='simulation'){const v=Number(vals['valor-do-imovel']||625000),pct=Number(vals['entrada-']||vals['entrada']||20),prazo=Number(vals['prazo-meses-']||60);modal('Resumo da simulação',`<div class="grid cols3">${kpi('Valor do imóvel',money(v),'referência ilustrativa')}${kpi('Entrada',money(v*pct/100),pct+'%')}${kpi('Saldo',money(v*(1-pct/100)),prazo+' parcelas')}</div><div class="spacer"></div><div class="subtle">Parcela-base: ${money(v*(1-pct/100)/prazo)}. Exemplo sem juros ou correção; confira a tabela do empreendimento.</div>`);return}
 if(f.dataset.context==='newflow'){closeModal();action('floweditor',{dataset:{value:vals['nome-do-fluxo']}});return}
 if(f.dataset.save==='Indicadores do resumo individual')state.individualMetrics=metrics.filter(m=>f.elements.namedItem('individual-'+m)?.checked);
 saveDemo();closeModal();shell();toast('Salvo nesta demonstração: '+f.dataset.save+'.');
});
document.addEventListener('change',e=>{
 const el=e.target;if(el.name==='tipo-de-cadastro'){state.propertyType=el.value;toast('Características atualizadas para '+el.value+'. Abra a aba Características.');return}
 if(el.dataset.leadstage!==undefined){leads[Number(el.dataset.leadstage)].stage=el.value;toast('Etapa atualizada na demonstração.');return}
 if(el.dataset.ownerlead!==undefined){leads[Number(el.dataset.ownerlead)].owner=el.value;toast('Responsável alterado. Isso não comprova pré-qualificação SDR.');return}
 if(el.id==='selectall')$$('.leadcheck').forEach(x=>x.checked=el.checked);
 if(['ownerfilter','tempfilter','originfilter'].includes(el.id))filterKanban();
 if(el.id==='propertytype')filterProperties();
 if(el.id==='funilselect'){const sdr=el.value.startsWith('SDR');if(sdr){$('#board').innerHTML=['Lead Novo','Tentativa 1','Tentativa 2','Atendimento Interessado'].map((t,i)=>`<div class="column"><div class="columnhead">${t}</div>${leadCard({...leads[i],stage:t,owner:'SDR'},i)}</div>`).join('')}else shell();}
 if(el.dataset.filter){state.filterPeriod=el.value;toast('Recorte selecionado: '+el.value+' · dados de demonstração.');if(el.value==='Personalizado')formModal('Selecionar período',[field('De','date','2026-11-01'),field('Até','date','2026-11-30')],'Aplicar período')}
});
function filterKanban(){let q=($('#kanbansearch')?.value||'').toLowerCase(),ow=$('#ownerfilter')?.value||'',t=$('#tempfilter')?.value||'',o=$('#originfilter')?.value||'';$$('.leadcard').forEach(c=>c.hidden=!(c.textContent.toLowerCase().includes(q)&&(!ow||c.dataset.owner===ow)&&(!t||c.dataset.temp===t)&&(!o||c.dataset.origin===o)))}
function filterProperties(){let q=($('#propertysearch')?.value||'').toLowerCase(),t=$('#propertytype')?.value||'';$('#propertygrid').innerHTML=properties.map((p,i)=>(p.name+' '+p.location+' ABR-034').toLowerCase().includes(q)&&(!t||p.type===t)?propertyCard(p,i):'').join('')||'<div class="empty">Nenhum imóvel neste filtro.</div>'}
document.addEventListener('input',e=>{if(e.target.id==='kanbansearch')filterKanban();if(e.target.id==='propertysearch')filterProperties();if(e.target.id==='basesearch')$$('#basetable tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));if(e.target.hasAttribute('data-chatsearch'))$$('.chatitem').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()))});
document.addEventListener('dragstart',e=>{let card=e.target.closest('.leadcard');if(card)e.dataTransfer.setData('text/plain',card.dataset.lead)});
document.addEventListener('drop',e=>{let col=e.target.closest('.column[data-stage]');if(col){e.preventDefault();let i=Number(e.dataTransfer.getData('text/plain'));if(leads[i]){leads[i].stage=col.dataset.stage;shell();toast('Lead movido para '+col.dataset.stage+'.')}}});
let initial=location.hash.slice(1).split('/');if(moduleNames[initial[0]]){state.route=initial[0];state.tab=decodeURIComponent(initial[1]||'')}if(state.role==='broker'&&!['painel','funil','atender','imoveis','plantao','conta','disponibilidade','producao','apresentacao'].includes(state.route))state.route='painel';shell();
